//! Exact inert attribute values remain data until native sink admission.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body><div id=mount></div></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://inert-attribute-units.test/",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}
#[test]
fn inert_attribute_units_all_owners_namespaces_attached_detached_and_id_reflection(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var html=document.implementation.createHTMLDocument('owner'),xml=document.implementation.createDocument(null,'Root'),generic=new Document(),template=xml.createElementNS('http://www.w3.org/1999/xhtml','template');for(var owner of [html,xml,generic,template.content.ownerDocument]){for(var node of [owner.createElement('span'),owner.createElementNS('urn:element','e:Root')]){node.setAttribute('title','v\ud800');var title=node.getAttributeNode('title'),map=node.attributes;node.setAttributeNS('urn:attr','one:Name','v\udfff');node.setAttributeNS('urn:\ud800','p:Raw\udfff','x\ud800Y\udfff');var held=node.getAttributeNodeNS('urn:attr','Name');if(title.value!=='v\ud800'||held.value!=='v\udfff'||node.getAttributeNS('urn:\ud800','Raw\udfff')!=='x\ud800Y\udfff'||map!==node.attributes||held.ownerDocument!==owner||held.ownerElement!==node)throw 'real exact sources';node.setAttributeNS('urn:attr','two:Name','v\ud800');if(node.getAttributeNodeNS('urn:attr','Name')!==held||held.prefix!=='one'||held.value!=='v\ud800')throw 'preserved identity and original prefix';held.value='next\udfff';if(node.getAttributeNS('urn:attr','Name')!=='next\udfff'||held.nodeValue!==held.value||held.textContent!==held.value)throw 'actual attached raw setter';node.removeAttributeNode(held);if(held.ownerElement!==null||held.ownerDocument!==owner||held.value!=='next\udfff'||map.length!==2)throw 'detached exact value';node.setAttributeNodeNS(held);node.setAttribute('id','id\ud800');node.setAttributeNS('urn:other','id','namespaced');if(node.id!=='id\ud800'||node.id==='id\ufffd'||node.getAttributeNS('urn:other','id')!=='namespaced')throw 'id reads exact null-namespace source';node.removeAttribute('id');if(node.id!=='')throw 'empty reflected id';}}
"#);}
#[test]
fn inert_attribute_units_clone_import_observation_and_conversion_effects(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=document.implementation.createDocument(null,'Root'),node=owner.documentElement;node.setAttribute('title','first\ud800');node.setAttributeNS('urn:attr','p:Name','ns\udfff');var title=node.getAttributeNode('title'),held=node.getAttributeNodeNS('urn:attr','Name'),clone=node.cloneNode(true),target=new Document(),copy=target.importNode(node,true),observer=new MutationObserver(function(){});observer.observe(node,{attributes:true,attributeOldValue:true});node.setAttribute('title','second\udfff');title.value='third\ud800';var order='';node.setAttributeNS({toString:function(){order+='n';return 'urn:attr';}},{toString:function(){order+='q';return 'q:Name';}},{toString:function(){order+='v';held.value='effect\ud800';return 'next\udfff';}});var records=observer.takeRecords();if(order!=='nqv'||records.length!==4||records[0].oldValue!=='first\ud800'||records[1].oldValue!=='second\udfff'||records[2].oldValue!=='ns\udfff'||records[3].oldValue!=='effect\ud800'||records[3].attributeNamespace!=='urn:attr'||records[3].attributeName!=='Name'||held.value!=='next\udfff'||held.prefix!=='p'||node.getAttributeNodeNS('urn:attr','Name')!==held)throw 'ordered exact original observation';if(clone.getAttribute('title')!=='first\ud800'||copy.getAttributeNS('urn:attr','Name')!=='ns\udfff'||copy.ownerDocument!==target||clone.ownerDocument!==owner||clone.isEqualNode(node)||!clone.isEqualNode(copy))throw 'native snapshot clone and inert import';var expected={},caught=false;try{node.setAttribute('title',{toString:function(){title.value='retained\ud800';throw expected;}});}catch(e){caught=e===expected;}if(!caught||title.value!=='retained\ud800'||observer.takeRecords().length!==1)throw 'author effects survive conversion error';observer.disconnect();
"#);}
#[test]
fn inert_attribute_units_native_transfer_refuses_before_source_or_activation_changes(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=document.implementation.createHTMLDocument('owner'),span=owner.createElement('span'),img=owner.createElement('img');owner.body.appendChild(span);span.setAttribute('title','passive\ud800');span.setAttribute('data-raw','kept\udfff');img.setAttribute('src','https://no-inert-raw.test/\ud800');img.setAttribute('onload','throw "never"\ud800');var title=span.getAttributeNode('title');
"#);
 p.state.rebuild(&d).unwrap();let before=(d.nodes.len(),p.state.retained,p.state.dom_commits);
 for code in ["document.body.appendChild(span);","document.importNode(span,true);","document.importNode(img,true);"]{assert_eq!(p.console_eval(&mut d,&mut f,code).errors,1,"{code}");assert_eq!((d.nodes.len(),p.state.retained,p.state.dom_commits),before);}
 run(&mut d,&mut f,&mut p,r#"
if(span.parentNode!==owner.body||span.ownerDocument!==owner||title.ownerElement!==span||title.value!=='passive\ud800'||img.getAttribute('src')!=='https://no-inert-raw.test/\ud800')throw 'refusal source prefix';span.removeAttribute('title');var result=document.body.appendChild(span);if(result!==span||span.ownerDocument!==document||!span.isConnected||span.getAttribute('data-raw')!=='kept\udfff'||title.ownerElement!==null||title.value!=='passive\ud800')throw 'supported metadata same identity after refusal';
"#);
 assert!(!p.has_navigation_request());assert!(p.take_dynamic_scripts().is_empty()&&p.take_dynamic_stylesheets().is_empty());let(a,b,c)=p.take_image_changes();assert!(a.is_empty()&&b.is_empty()&&c.is_empty());
}
#[test]
fn inert_attribute_units_no_slot_and_captured_child_callers_preserve_current_access(){
 let(mut d,mut f,mut p)=fixture();let node_limit=p.state.node_limit;p.state.node_limit=d.nodes.len();run(&mut d,&mut f,&mut p,r#"
var owner=new Document(),node=owner.createElement('div');node.setAttributeNS('urn:attr','p:Name','value\ud800');var clone=node.cloneNode(true);if(!clone.isEqualNode(node)||clone.getAttributeNS('urn:attr','Name')!=='value\ud800')throw 'no-slot source';
"#);p.state.node_limit=node_limit;run(&mut d,&mut f,&mut p,r#"
var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var w=frame.contentWindow,saved=w.Function('node','value',"node.setAttributeNS('urn:attr','p:Name',value);"),calls=0,value={toString:function(){calls++;return 'changed\udfff';}};saved(node,value);if(calls!==1||node.getAttributeNS('urn:attr','Name')!=='changed\udfff')throw 'same-origin exact conversion';
"#);
 p.set_location(&crate::navigation::address("https://other-attribute-units.test/",&crate::navigation::Location::home()).unwrap());let before=(d.nodes.len(),p.state.retained,p.state.dom_commits);assert_eq!(p.console_eval(&mut d,&mut f,"saved(node,value);").errors,1);assert_eq!((d.nodes.len(),p.state.retained,p.state.dom_commits),before);run(&mut d,&mut f,&mut p,"if(calls!==1)throw 'captured origin before author conversion';");
}
